<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -Dversion=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1.0-SNAPSHOT&#39;</span></span>
